#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class BDirectAttackBasicLoopTests {
  const string Root="D:/Project/LASTRAIL/",QA=Root+"QA/CombatBMigration-20261002/AttackBuffConsumer/";
  static JObject Owned()=>(JObject)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-owned-profile-observed-sql-test-20261001.json"))["profile"];
  static CombatDefinitionIndex Definition()=>CombatDefinitionIntake.Read(JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-definition-intake-20261001.json")));
  static BCarriageBuffDefinitions Defs(){string j=File.ReadAllText(Root+"QA/CombatBMigration-20261002/BuffConsumer/original-definitions.json");using var sha=SHA256.Create();return new BCarriageBuffDefinitions(j,BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(j))).Replace("-","").ToLowerInvariant());}
  static BCombatFormation Formation(int count=1)=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,Enumerable.Range(0,count).Select(i=>new BCombatSlot("car"+i,i==0?"op_mira":null)));
  static JObject Packet(int count=1){var p=JObject.Parse(File.ReadAllText(Root+"QA/CombatBMigration-20261002/AttackConsumer/local-original-input.json"));p["formation"]=Formation(count).Capture();var rows=(JArray)p["entities"];var car=rows.Single(x=>(string)x["id"]=="car0");for(int n=1;n<count;n++){var c=(JObject)car.DeepClone();c["id"]="car"+n;c["definitionId"]="LOCAL_ORIGINAL_car"+n;c["slot"]=n;rows.Add(c);var g=(JObject)((JArray)p["geometry"]).Single(x=>(string)x["sourceId"]=="enemy"&&(string)x["targetId"]=="car0").DeepClone();g["targetId"]="car"+n;g["targetSlot"]=n;((JArray)p["geometry"]).Add(g);}return p;}
  static JObject Entity(JObject p,string id)=>(JObject)((JArray)p["entities"]).Single(e=>(string)e["id"]==id);
  static JObject Q(long n,long d=1)=>new JObject{["numerator"]=n.ToString(),["denominator"]=d.ToString()};
  static BDirectAttackInput Input(JObject packet=null){packet=packet??Packet();((JArray)packet["sourceEvidence"]).Add(new JObject{["sourceId"]="LOCAL_COMPOSITION_TRIAL_BOUNDARY_NOT_OPERATING_ENEMY_OR_B_BASE",["sha256"]=BDirectAttackInput.Digest(packet).Substring(7)});var o=Owned();return new BDirectAttackInput(packet,BDirectAttackInput.Digest(packet),Formation(((JArray)packet["formation"]["slots"]).Count),o,BDirectAttackInput.Digest(o),Definition());}
  static JObject Candidate(string type="BCB01",int rank=5,int count=1)=>(JObject)((JArray)JObject.Parse(File.ReadAllText(QA+"original-candidates.json"))["candidates"]).Single(x=>(string)x["name"]==type+"_R"+rank+"_SLOTS"+count)["departure"].DeepClone();
  static JObject BindingPacket(BDirectAttackInput input,string type="BCB01",int rank=5,string category="ENEMY"){
   int count=input.Formation.Slots.Count;var d=Candidate(type,rank,count);return new JObject{["version"]=BDirectAttackBuffBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["attackInputHash"]=input.OriginalHash,["definitionHash"]=Defs().Hash,["departure"]=d,
    ["initial"]=new JObject{["contextId"]="LOCAL_ATTACK_BUFF_"+type+"_R"+rank+"_"+count,["mode"]="EXTERIOR",["cars"]=new JArray(((JArray)d["cars"]).Select(c=>new JObject{["slot"]=c["slot"].DeepClone(),["body"]="NORMAL",["actor"]=(string)c["occupant"]["kind"]=="CARGO"?"ABSENT":"UP"}))},
    ["targetCategories"]=new JArray(new JObject{["targetId"]="enemy",["category"]=category})};}
  static BDirectAttackBuffBinding Binding(JObject packet=null,string type="BCB01",int rank=5,string category="ENEMY"){var i=Input(packet);var b=BindingPacket(i,type,rank,category);return new BDirectAttackBuffBinding(i,Defs(),b,BDirectAttackInput.Digest(b));}
  static BDirectAttackBuffSession Session(JObject packet=null,string type="BCB01",int rank=5,string category="ENEMY",int capacity=10000)=>new BDirectAttackBuffSession(Binding(packet,type,rank,category),capacity);
  static BDirectAttackBasicLoopBinding LoopBinding(BDirectAttackBuffBinding b,bool enemy=false,bool reverse=false){
   var routes=new JArray(new JObject{["sourceId"]="op_mira",["targetId"]="enemy"});if(enemy)routes.Add(new JObject{["sourceId"]="enemy",["targetId"]="car0"});if(reverse)routes=new JArray(routes.Reverse().Select(x=>x.DeepClone()));
   var p=new JObject{["version"]=BDirectAttackBasicLoopBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["compositionHash"]=b.OriginalHash,["targets"]=routes};return new BDirectAttackBasicLoopBinding(b,p,BDirectAttackInput.Digest(p));
  }
  static BDirectAttackBasicLoop Loop(JObject packet=null,bool enemy=false,int capacity=10000,string type="BCB01")=>new BDirectAttackBasicLoop(LoopBinding(Binding(packet,type),enemy),capacity);
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"expected "+a+" actual "+b);
  static JToken State(BDirectAttackBasicLoop s,string key)=>s.Capture()["state"]["direct"][key];
  [Test] public void SelectionHoldReleasePreservesOtherHoldUserPauseSpeedAndReplay(){
   var s=Loop();var method=typeof(BDirectAttackBasicLoop).GetMethod("SetHold");Assert.NotNull(method,"Native reason-owned holds missing");
   void Hold(string id,string owner,bool held)=>method.Invoke(s,new object[]{id,owner,held});
   s.SetSpeed("speed",4);Hold("select-start","selection:grant",true);Hold("recovery-start","recovery",true);s.SetPaused("user-pause",true);
   Hold("select-done","selection:grant",false);Assert.IsTrue(s.Paused);s.SetPaused("user-resume",false);Assert.IsTrue(s.Paused);
   s.Advance("blocked",1000000,100);Assert.AreEqual(0,s.Tick);Hold("recovery-done","recovery",false);Assert.IsFalse(s.Paused);
   Assert.AreEqual(4,(int)State(s,"clock")["speedHalfUnits"]);var before=s.Capture();Hold("select-start","selection:grant",true);Same(before,s.Capture());
   var binding=(BDirectAttackBasicLoopBinding)typeof(BDirectAttackBasicLoop).GetField("binding",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(s);
   var restored=BDirectAttackBasicLoop.Restore(s.Capture(),binding,10000);Same(s.Capture(),restored.Capture());restored.Advance("resume",10000,10);Assert.Greater(restored.Tick,0);
  }
  [Test] public void ClockActuallyDispatchesRecurringBasicToOriginalBuffHpAndReceipts(){var s=Loop();var r=s.Advance("elapsed",36010000,3601);Assert.AreEqual(3601,s.Tick);Assert.AreEqual(3,r.Hits.Count);CollectionAssert.AreEqual(new long[]{1,1801,3601},r.Hits.Select(h=>h.Attack.Tick));CollectionAssert.AreEqual(new int[]{41,41,41},r.Hits.Select(h=>h.Attack.Hp.HpLoss));Assert.AreEqual(577,s.Hp("enemy"));Assert.AreEqual(5401,(long)State(s,"next")["op_mira"]);Assert.AreEqual(3,((JArray)s.Capture()["state"]["buffs"]["journal"]).Count);}
  [Test] public void LargeElapsedAndSplitElapsedHaveIdenticalOwnedStateAndImpactIdentities(){var a=Loop(enemy:true);var b=Loop(enemy:true);var one=a.Advance("one",44010000,4401);var hits=new System.Collections.Generic.List<BDirectAttackBuffReceipt>();for(int i=0;i<44;i++)hits.AddRange(b.Advance("part"+i,1000000,100).Hits);hits.AddRange(b.Advance("last",10000,1).Hits);Assert.AreEqual(a.Hp("enemy"),b.Hp("enemy"));Assert.AreEqual(a.Hp("car0"),b.Hp("car0"));Same(State(a,"clock"),State(b,"clock"));Same(State(a,"next"),State(b,"next"));Same(a.Capture()["state"]["buffs"],b.Capture()["state"]["buffs"]);CollectionAssert.AreEqual(one.Hits.Select(h=>h.Attack.EventId),hits.Select(h=>h.Attack.EventId));}
  [Test] public void DebtAndSubStepRemainderAreConsumedByTheOriginalSingleClock(){var s=Loop();Assert.AreEqual(0,s.Advance("half",5000,100).Hits.Count);Assert.AreEqual(0,s.Tick);Assert.AreEqual(10000,(long)State(s,"clock")["debtHalfTicks"]);var r=s.Advance("credit",18005000,1);Assert.AreEqual(1,r.Hits.Count);Assert.AreEqual(1,s.Tick);Assert.AreEqual(1800,s.Advance("debt",0,1799).Tick);Assert.AreEqual(1,s.Advance("due",0,1).Hits.Count);Assert.AreEqual(1801,s.Tick);}
  [TestCase(2,1)][TestCase(3,1)][TestCase(4,2)] public void OriginalSpeedAndFractionalCreditArePreserved(int speed,int steps){var s=Loop();s.SetSpeed("speed",speed);s.Advance("credit",10000,100);Assert.AreEqual(steps,s.Tick);Assert.AreEqual(speed==3?10000:0,(long)State(s,"clock")["debtHalfTicks"]);}
  [Test] public void PauseConsumesNeitherDebtNorHpAndReplayOfAnOldBatchStillWorks(){var s=Loop();var first=s.Advance("first",10000,1);s.Advance("debt",100000,0);s.SetPaused("pause",true);var clock=State(s,"clock");var hp=s.Hp("enemy");Assert.AreEqual(0,s.Advance("paused",9990000,1000).Hits.Count);Same(clock,State(s,"clock"));Assert.AreEqual(hp,s.Hp("enemy"));Assert.AreSame(first,s.Advance("first",10000,1));s.SetPaused("resume",false);Assert.AreEqual(11,s.Advance("flush",0,100).Tick);}
  [Test] public void TieUsesOriginalActorArrayNotRouteDictionaryOrder(){var b=Binding();var s=new BDirectAttackBasicLoop(LoopBinding(b,true,true),10000);var r=s.Advance("first",10000,1);CollectionAssert.AreEqual(new[]{"op_mira","enemy"},r.Hits.Select(h=>h.Attack.SourceId));Assert.AreEqual(659,s.Hp("enemy"));Assert.AreEqual(964,s.Hp("car0"));}
  [Test] public void UnsuppliedEnemyActorIsExplicitlyExcludedWithoutInventedTargetSearch(){var b=LoopBinding(Binding());CollectionAssert.AreEqual(new[]{"enemy"},b.UnsuppliedActors);var s=new BDirectAttackBasicLoop(b,10000);var r=s.Advance("time",44010000,4401);Assert.AreEqual(3,r.Hits.Count);Assert.AreEqual(1000,s.Hp("car0"));}
  [Test] public void BasicDriverDoesNotRequireAnUltimateAutoCommand(){var s=Loop();Assert.AreEqual(2,s.Advance("no-ultimate-auto-input",18010000,1801).Hits.Count);Assert.AreEqual(618,s.Hp("enemy"));}
  [Test] public void BreakingBodyDisablesNewBuffButLivingOperatorKeepsRecurringBasic(){var p=Packet();Entity(p,"car0")["maxHp"]=20;var s=Loop(p,true,type:"BCB06");var r=s.Advance("time",18010000,1801);Assert.AreEqual(3,r.Hits.Count);Assert.IsTrue(r.Hits[1].Attack.Hp.CarriageDown);Assert.AreEqual(187,(long)r.Hits[1].Attack.Calculation["effectiveDefense"]["numerator"]);Assert.AreEqual(0,s.Hp("car0"));Assert.AreEqual(1520,s.Hp("op_mira"));Assert.AreEqual(32,r.Hits[2].Attack.Hp.HpLoss);Assert.AreEqual(0,(long)r.Hits[2].BuffSource["damageBps"]);Assert.AreEqual(636,s.Hp("enemy"));Assert.AreEqual(6,r.Hits[1].Attack.Hp.TrainHpLoss);Assert.AreEqual(0,(long)State(s,"next")["enemy"]-2201);}
  [Test] public void DownActorIsNotAutomaticallyAcceptedOnLaterTicks(){var p=Packet();Entity(p,"enemy")["attack"]=Q(4000);var b=Binding(p);var packet=LoopBinding(b,true).Capture();packet["targets"][1]["targetId"]="op_mira";var binding=new BDirectAttackBasicLoopBinding(b,packet,BDirectAttackInput.Digest(packet));var s=new BDirectAttackBasicLoop(binding,10000);var r=s.Advance("time",44010000,4401);Assert.AreEqual(2,r.Hits.Count);Assert.AreEqual(0,s.Hp("op_mira"));Assert.AreEqual(659,s.Hp("enemy"));Assert.AreEqual(1801,(long)State(s,"next")["op_mira"]);Assert.AreEqual("RUNNING",s.Outcome);}
  [Test] public void DefeatStopsClockDuringBatchAndFutureElapsedIsNoOp(){var p=Packet();Entity(p,"train")["maxHp"]=1;var b=Binding(p);var packet=LoopBinding(b,true).Capture();packet["targets"][1]["targetId"]="train";var s=new BDirectAttackBasicLoop(new BDirectAttackBasicLoopBinding(b,packet,BDirectAttackInput.Digest(packet)),10000);Assert.AreEqual("FAILURE",s.Advance("end",10000000,1000).Outcome);Assert.AreEqual(1,s.Tick);var clock=State(s,"clock");Assert.AreEqual(0,s.Advance("after",10000000,1000).Hits.Count);Same(clock,State(s,"clock"));}
  [Test] public void ExactReplayAndRestoredFutureAutomaticExecutionRemainEquivalent(){var b=LoopBinding(Binding(),true);var s=new BDirectAttackBasicLoop(b,10000);var r=s.Advance("first",18010000,1801);var before=s.Capture();Assert.AreSame(r,s.Advance("first",18010000,1801));Same(before,s.Capture());Assert.Throws<ArgumentException>(()=>s.Advance("first",18010001,1801));Same(before,s.Capture());var restored=BDirectAttackBasicLoop.Restore(before,b,10000);Same(before,restored.Capture());var a=s.Advance("later",26000000,2600);var c=restored.Advance("later",26000000,2600);CollectionAssert.AreEqual(a.Hits.Select(h=>h.Attack.EventId),c.Hits.Select(h=>h.Attack.EventId));Same(s.Capture(),restored.Capture());Assert.Throws<ArgumentException>(()=>BDirectAttackBuffSession.Restore((JObject)before["state"],b.Composition,10000));}
  [TestCase("geometry")][TestCase("distance")][TestCase("arithmetic")][TestCase("child-capacity")]
  public void AFailureAfterEarlierImpactsNeverPublishesClockHpBuffNextOrReceipt(string failure){var p=Packet();int capacity=10000;if(failure=="geometry")foreach(var g in (JArray)p["geometry"])g["validUntilTick"]=1800;if(failure=="distance")((JArray)p["geometry"]).Single(g=>(string)g["sourceId"]=="op_mira")["distanceMm"]=1001;if(failure=="arithmetic")((JArray)Entity(p,"op_mira")["attackSources"]).Add(new JObject{["sourceId"]="LOCAL_OVERFLOW",["ownerId"]="op_mira",["group"]="EQUIPMENT_ATK",["valueBps"]=9007199254740991L});if(failure=="child-capacity")capacity=2;var s=Loop(p,capacity:capacity);var before=s.Capture();Assert.Catch(()=>s.Advance("fail",36010000,3601));Same(before,s.Capture());}
  [Test] public void WrapperCapacityReplayAndRestoredOverflowPreserveAllOwners(){var b=LoopBinding(Binding());var s=new BDirectAttackBasicLoop(b,2);var first=s.SetSpeed("one",4);s.SetPaused("two",true);var before=s.Capture();Assert.AreSame(first,s.SetSpeed("one",4));Assert.Catch(()=>s.Advance("three",10000,1));Same(before,s.Capture());var restored=BDirectAttackBasicLoop.Restore(before,b,2);Assert.Catch(()=>restored.Advance("three",10000,1));Same(before,restored.Capture());}
  [TestCase("hp")][TestCase("clock")][TestCase("next")][TestCase("result")][TestCase("command")][TestCase("binding")][TestCase("version")]
  public void CacheTamperingFailsFullOriginalAutomaticReplay(string part){var b=LoopBinding(Binding());var s=new BDirectAttackBasicLoop(b,10000);s.Advance("first",18010000,1801);var cache=s.Capture();if(part=="hp")cache["state"]["direct"]["enemies"]["enemy"]["hp"]=1;if(part=="clock")cache["state"]["direct"]["clock"]["completedSteps"]=1;if(part=="next")cache["state"]["direct"]["next"]["op_mira"]=1;if(part=="result")cache["results"][0]["hits"][0]["beforeShield"]=1;if(part=="command")cache["commands"][0]["elapsed"]=1;if(part=="binding")cache["bindingHash"]="bad";if(part=="version")cache["version"]=BDirectAttackBuffSession.Version;Assert.Catch(()=>BDirectAttackBasicLoop.Restore(cache,b,10000));}
  [TestCase("hash")][TestCase("missinggeometry")][TestCase("duplicate")][TestCase("unsupported")][TestCase("kind")]
  public void TargetBindingIsStrictAndNeverInventsMissingPolicy(string part){var b=Binding();var packet=LoopBinding(b).Capture();if(part=="missinggeometry")packet["targets"][0]["targetId"]="op_mira";if(part=="duplicate")((JArray)packet["targets"]).Add(packet["targets"][0].DeepClone());if(part=="unsupported")packet["targets"][0]["sourceId"]="car0";if(part=="kind")packet["targets"][0]["targetId"]="train";Assert.Catch(()=>new BDirectAttackBasicLoopBinding(b,packet,part=="hash"?"bad":BDirectAttackInput.Digest(packet)));}
  [Test] public void BindingAndResultsAreDetachedFromCallerMutation(){var b=LoopBinding(Binding());b.Capture()["targets"][0]["targetId"]="train";var s=new BDirectAttackBasicLoop(b,10000);var r=s.Advance("first",10000,1);r.Hits[0].BuffSource["damageBps"]=999;s.Capture()["results"][0]["hits"][0]["beforeShield"]=999;Assert.AreEqual(3000,(long)r.Hits[0].BuffSource["damageBps"]);Assert.AreEqual(659,s.Hp("enemy"));}
  [Test] public void ActualAutomatic1024SourceLimitRejectsWholeNextBatchButPreservesReplayAndRestore(){
   var p=Packet();p["stepTimeSpanTicks"]=10000000;Entity(p,"enemy")["maxHp"]=1000000;foreach(var g in (JArray)p["geometry"])g["validUntilTick"]=5000000;
   var b=LoopBinding(Binding(p));var s=new BDirectAttackBasicLoop(b,5000);var full=s.Advance("full",20470000000,2047);
   Assert.AreEqual(1024,full.Hits.Count);Assert.AreEqual(2047,s.Tick);Assert.AreEqual(958016,s.Hp("enemy"));Assert.AreEqual(1024,((JArray)s.Capture()["state"]["buffs"]["journal"]).Count);
   var before=s.Capture();Assert.Catch(()=>s.Advance("over",20000000,2));Same(before,s.Capture());Assert.AreSame(full,s.Advance("full",20470000000,2047));
   var r=BDirectAttackBasicLoop.Restore(before,b,5000);Same(before,r.Capture());Assert.Catch(()=>r.Advance("over",20000000,2));Same(before,r.Capture());
  }
  [Test] public void VictoryStopsAtActualDueTickAndFutureClockDoesNotRestart(){var p=Packet();Entity(p,"enemy")["maxHp"]=41;var s=Loop(p,true);var r=s.Advance("end",10000000,1000);Assert.AreEqual("VICTORY",r.Outcome);Assert.AreEqual(1,s.Tick);Assert.AreEqual(1,r.Hits.Count);var clock=State(s,"clock");Assert.AreEqual(0,s.Advance("later",10000000,1000).Hits.Count);Same(clock,State(s,"clock"));}
  [Test] public void AnInternalConsumerCannotChangeTrustedTieOrderAndSuppressAnOriginalHit(){
   var p=Packet();Entity(p,"enemy")["attack"]=Q(4000);var composition=Binding(p);var packet=LoopBinding(composition,true).Capture();packet["targets"][1]["targetId"]="op_mira";
   var b=new BDirectAttackBasicLoopBinding(composition,packet,BDirectAttackInput.Digest(packet));
   var value=typeof(BDirectAttackBasicLoopBinding).GetProperty("OrderedSources",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(b);
   if(value is System.Collections.Generic.IList<string> list){try{list[0]="enemy";list[1]="op_mira";}catch(NotSupportedException){}}
   var s=new BDirectAttackBasicLoop(b,10000);var r=s.Advance("tie",10000,1);Assert.AreEqual(2,r.Hits.Count,"Trusted original tie order must preserve Mira's due hit before down");Assert.AreEqual("op_mira",r.Hits[0].Attack.SourceId);Assert.AreEqual(659,s.Hp("enemy"));
   Same(s.Capture(),BDirectAttackBasicLoop.Restore(s.Capture(),b,10000).Capture());
  }
  [Test] public void OriginalAcceptedActionSequencePersistsAcrossBatchesAndRestore(){
   var b=LoopBinding(Binding(),true);var s=new BDirectAttackBasicLoop(b,10000);s.Advance("first",10000,1);Assert.AreEqual(2L,(long?)s.Capture()["sequence"]);
   s.Advance("next",18000000,1800);Assert.AreEqual(3L,(long?)s.Capture()["sequence"]);var restored=BDirectAttackBasicLoop.Restore(s.Capture(),b,10000);restored.Advance("enemy",4000000,400);s.Advance("enemy",4000000,400);Assert.AreEqual(4L,(long?)s.Capture()["sequence"]);Same(s.Capture(),restored.Capture());
  }
 }
